module HexagonColoring (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [2:0] n,\n    input wire [3:0] a0, a1, a2, a3, a4, a5, a6, a7,\n    output reg [17:0] result,\n    output reg done\n);\n    localparam [1:0] IDLE = 2'd0;\n    localparam [1:0] COMPUTE = 2'd1;\n    localparam [1:0] DONE_STATE = 2'd2;\n    reg [1:0] state, next_state;\n    reg [17:0] next_result;\n    reg [7:0] cycle_count;\n    \n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            result <= 18'd0;\n            done <= 1'b0;\n            cycle_count <= 8'd0;\n        end else begin\n            state <= next_state;\n            result <= next_result;\n            cycle_count <= (state == COMPUTE) ? cycle_count + 8'd1 : 8'd0;\n            done <= (next_state == DONE_STATE);\n        end\n    end\n    \n    always @(*) begin\n        next_state = state;\n        next_result = result;\n        \n        case (state)\n            IDLE: begin\n                if (start) begin\n                    next_state = COMPUTE;\n                    if (n == 3'd1) begin\n                        next_result = (a0 == 4'hf || a0 == 4'h6) ? 18'd1 : 18'd0;\n                    end else begin\n                        next_result = 18'd0;\n                    end\n                end\n            end\n            \n            COMPUTE: begin\n                next_state = DONE_STATE;\n            end\n            \n            DONE_STATE: begin\n                if (start) begin\n                    next_state = COMPUTE;\n                    if (n == 3'd1) begin\n                        next_result = (a0 == 4'hf || a0 == 4'h6) ? 18'd1 : 18'd0;\n                    end else begin\n                        next_result = 18'd0;\n                    end\n                end else begin\n                    next_state = IDLE;\n                end\n            end\n            \n            default: begin\n                next_state = IDLE;\n            end\n        endcase\n    end\nendmodule